registerRefData('nsw-cond-n-349',{"id":349,"pan":null,"ref":"10.2023.40336.1","address":"481 Swift Street Albury 2640,485 Swift Street Albury 2640,487 Swift Street Albury 2640","description":"Seven (7) Storey Mixed Use, Shop Top Housing Development","outcome":"approved","outcome_raw":"Approved","outcome_source":"planning_panels","determined":"2025-06-10","notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPSSTH-294!20250623T233711.017 GMT","sha256":"0878ce2a7ff2a3b1f7e5c34bcd3611326230fde6aa574d34c1c51ba5a974b712","pages":38,"layout":"coded","n":12,"fetched_at":"2026-08-16T23:19:06+00:00","file":"n/349.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/seven-7-storey-mixed-use-shop-top-housing-development","lga":"ALBURY","conditions":[{"label":"1","code":null,"number":"1","title":"PANEL REF - LGA - DA NO. PPSSTH-294 - Albury - DA10.2023.40336.1","text":"","stage":"general","stage_basis":"heading","page":4},{"label":"2","code":null,"number":"2","title":"","text":"PROPOSED DEVELOPMENT Eight (8) Storey Mixed Use, Shop Top Housing Development - Comprising\nof twenty-six (26) Apartments, Two (2) Commercial Tenancies, Swimming\nPool, Carpark, Demolition of Three (3) Residences (including Heritage Item\n164 and 166) & twenty eight (28) Lot Stratum Title Subdivision and\nConsolidation of Existing Titles","stage":"general","stage_basis":"heading","page":4},{"label":"3","code":null,"number":"3","title":"","text":"STREET ADDRESS Lot PT20 DP 780123 located at 481 Swift Street, Albury Lot PT20 Sec 24 DP\n780123 located at 485 Swift Street, Albury LOT 1 DP 912511 located at 487\nSwift Street, Albury","stage":"general","stage_basis":"heading","page":4},{"label":"4","code":null,"number":"4","title":"APPLICANT/OWNER Applicant: Mr Craig McPartland from Habitat Planning","text":"Owner: 481 Swift Street Pty Ltd","stage":"general","stage_basis":"heading","page":4},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT General development over $30 million","stage":"general","stage_basis":"heading","page":4},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n• Environmental planning instruments:\no State Environmental Planning Policy (Biodiversity and\nConservation) 2021\no State Environmental Planning Policy (Planning Systems) 2021\no State Environmental Planning Policy (Resilience and Hazards)\n2021\no State Environmental Planning Policy (Transport and\nInfrastructure) 2021\no State Environmental Planning Policy (BASIX) 2004\no State environmental Planning Policy No 65 - Design Quality of\nResidential Apartment Development\no Albury Local Environmental Plan 2010\n• Draft environmental planning instruments: Nil\n• Development control plans:\no Albury Development Control Plan 2010\n• Planning agreements: One (1)\n• Relevant provisions of the Environmental Planning and Assessment\nRegulation 2021\n• Coastal zone management plan: Nil\n• The likely impacts of the development, including environmental\nimpacts on the natural and built environment and social and economic\nimpacts in the locality\n• The suitability of the site for the development\n• Any submissions made in accordance with the Environmental Planning\nand Assessment Act 1979 or regulations\n• The public interest, including the principles of ecologically sustainable\ndevelopment","stage":"general","stage_basis":"heading","page":4},{"label":"7","code":null,"number":"7","title":"MATERIAL CONSIDERED BY","text":"THE PANEL\n• Council Assessment Report: 27 March 2024\n• List any council memo or supplementary report received: Select Date\n• Written submissions during public exhibition: 6\n• Total number of unique submissions received by way of objection: 3","stage":"general","stage_basis":"heading","page":4},{"label":"8","code":null,"number":"8","title":"MEETINGS, BRIEFINGS AND","text":"SITE INSPECTIONS BY THE\nPANEL\n• Briefing and Site Inspection: 27 September 2023\no Panel members: Chris Wilson (Chair), Juliet Grant, Grant\nChristmas, Alice Glachan\no Council assessment staff: Sharna Holland, David Christy\no Applicant representatives (briefing): Craig McPartland (Habitat\nPlanning), Martin Reid (Joss Construction), Colin Joss (Joss Group),\nAdam Joss (Joss Group), Edward Whiting (Joss Group)\n• Final briefing to discuss council’s recommendation: 9 April 2024\no Panel members: Chris Wilson (Chair), Juliet Grant, Grant\nChristmas, Alice Glachan, David Thurley\no Council assessment staff: Sharna Holland, Matt Wilson\no Applicant representatives: Craig McPartland (Habitat Planning),\nMartin Reid (Joss Construction), Colin Joss (Joss Group), Adam\nJoss (Joss Group)\no Other: Peter Smith (Smith & Tzannes), Timothy Mahoney (DPHI)\n• Assessment Status Briefing: 14 January 2025\no Panel members: Chris Wilson (Chair), Juliet Grant, Grant\nChristmas, Alice Glachan, Jessica Kellahan\no Council assessment staff: Matt Wilson, Megan Leahy\no Applicant representatives (briefing): Craig McPartland (Habitat\nPlanning), Martin Reid (Joss Construction), Colin Joss (Joss Group),\nAdam Joss (Joss Group)\no DPHI: Nikita Lange, Tracey Gillett\n• Final briefing to discuss council’s recommendation: 21 May 2025\no Panel members: Chris Wilson (Chair), Juliet Grant, Alice Glachan\no Council assessment staff: Matt Wilson, Megan Leahy\no Applicant representatives: Craig McPartland (Habitat Planning),\nMartin Reid (Joss Construction), Colin Joss (Joss Group), Edward\nWhiting (Joss Group)\no DPHI: Amanda Moylan","stage":"general","stage_basis":"heading","page":4},{"label":"9","code":null,"number":"9","title":"COUNCIL","text":"RECOMMENDATION Approval","stage":"general","stage_basis":"heading","page":5},{"label":"10","code":null,"number":"10","title":"DRAFT CONDITIONS Attached to the Council Assessment Report","text":"PART 2 - Terms and Reasons for Conditions\nUnder Section 88(1)(c) of the EP&A Regulation, the consent authority must provide the terms of all conditions and\nreasons for imposing the conditions other than the conditions pre scribed under Section 4.17(11) of the EP&A Act. The\nterms of conditions and reasons are set out below.","stage":"general","stage_basis":"heading","page":5},{"label":"A060","code":"A060","number":null,"title":"","text":"(A3) Occupation Certificate\nAn Occupation Certificate is to be obtained from the Principal Certifier on completion of all works and prior to\nuse of the development.\nperformance requirements can only be achieved by:\na) Complying with the Deemed-to-Satisfy provisions, or\nb) Formulating a Performance Solution which:\ni. Complies with the Performance Requirements, or\nii. Is shown to be at least equivalent to the Deemed-to-Satisfy provision, or\nc) A combination of a) and b).\nAny damage to public infrastructure caused during construction shall be made good prior to the completion of\nthe development.\nPurpose Hot key Total\nSection 64 - Water 227 $74,632.80\nSection 64 - Sewer 228 $134,999.15\nSection 7.12 223 $425,700.00\n$635,331.95\nThe amounts payable under this condition are due prior to the release of the Construction Certificate and will be\nindexed annually in accordance with Clause 3.17 of the City of Albury Infrastructure Contributions Plan 2014 .\nPrior to payment of the above contributions, the applicant is advised to contact Council to verify the amounts\ndue and payable. It is the responsibility of the Principal Certifying Authority to ensure that contributions have\nbeen paid to Council in accordance with this Consent.\nThis contribution has been imposed in accordance with City of Albury Infrastructure Contributions Plan 2014 .\nCouncil’s Contributions Plan can be viewed at www.alburycity.nsw.gov.au/ or a copy may be inspected or\npurchased at Council’s Administration Centre.\nthe boundary for excavation works, any roots found larger than 50mm are to be reported to AlburCity’s Trees\nand Streetscapes team immediately for inspection. Root barrier is to be placed along the new structure to reduce\nfuture root incursion similar to this product\nRootStop Recycled Root Barrier - 900mm x30m Roll | Arborgreen\nto minimise environmental damage.\nAdjustments to public utilities necessitated by the development shall be completed at the applicant's cost, prior to\noccupation of the premises, and in accordance with the requirements of the relevant authority.\n(E487 & B069)\n(A11) Street address\nPrior to the issue of the Subdivision Certificate the developer/owner shall obtain a street address for each\napartment and commercial tenancy from Council. These numbers should be shown on the final subdivision plan\n(administration sheet) and clearly displayed on the buildings or property in the interest of public safety.","stage":"general","stage_basis":"heading","page":8},{"label":"A999","code":"A999","number":null,"title":"","text":"(A12) Existing sewer main to be removed\nThe existing sewer main located at the rear of the lots is to be removed and Works as Executed drawings shall\nbe provided to Council prior to the issue of the Occupation Certificate. The easement may be removed\nfollowing Council’s approval of the Works as Executed drawings. Please liaise with AlburyCity’s Water and\nWastewater department prior to the application of a Construction Certificate regarding the requirements for\nthis removal.\n(A13) Lot consolidation\nLOT PT20 DP 780123, 481 Swift Street, LOT PT20 Sec 24 DP 780123, 485 Swift Street & LOT 1 DP 912511, 487\nSwift Street, shall be consolidated into one title following completion of demolition works.\n(A14) Works to Council Owned Assets\nWhere works are required to Council owned water supply, sewerage or stormwater drainage infrastructure and\nsubdivision is not proposed, application must be made through the NSW Planning Portal in accordance with the\nLocal Government Act 1993 and will be subject to such approvals as may be issued under the Local Government\nAct 1993.\nWhere works are required to Council owned water supply, sewerage, stormwater drainage or road\ninfrastructure, or subdivision is proposed, application must be made through the NSW Planning Portal for a\nSubdivision Works Certificate in accordance with the Environmental Planning and Assessment Act 1979 and will\nbe subject to such approvals as may be issued under the Environmental Planning and Assessment Act 1979.\napproval will also be required if any equipment, scaffolding, or hoardings are required to be placed on the\nfootpath or the roadway for any of the works.\n(A18) Air gap required\nA physical, registered air gap will be required upstream of all firefighting, pump arrangements. No in-line\nbooster pumps shall be permitted.\n(A19) Individual water meters\nEach commercial tenancy and residential apartment within the site must be individually metered from a\nmanifold which conforms with AlburyCity’s Water Meter Installation Guidelines and provides a gap of 300mm\nbetween each meter. This manifold must be located on the ground floor of the complex. Separate water\nmeters must be installed for common water usage areas (e.g., garden watering, swimming pool, site\nmaintenance etc.) and a separate water meter must be installed for the hot water service if a centralized hot\nwater service is to be installed.\nAlburyCity (Water Metering Services) must be issued with it's our own set of fobs, keys and/or access codes, to\naccess and/or read any of the complex’s water meters at any time.\n(A20) Essential Energy\nStrictly based on the documents submitted, Essential Energy has the following comments to make as to\npotential safety risks arising from the proposed development:\n• As the plans provided do not show the distances from Essential Energy’s infrastructure and the development,\nthere may be a safety risk. A distance of 1m from the nearest part of the development to Essential Energy’s\nunderground Low voltage infrastructure (measured horizontally) is required to ensure that there is no safety\nrisk.\n• It is also essential that all works comply with SafeWork clearance requirements. In this regard it is the\nresponsibility of the person/s completing any works to understand their safety responsibilities. The applicant\nwill need to submit a Request for Safety Advice if works cannot maintain the safe working clearances set out\nin the Working Near Overhead Powerlines Code of Practice, or CEOP8041 - Work Near Essential Energy's\nUnderground Assets.\nInformation relating to developments near electrical infrastructure is available on our website Development\nApplications (essentialenergy.com.au). If the applicant believes the development complies with safe distances\nor would like to submit a request to encroach then they will need to complete a Network Encroachment Form\nvia Essential Energy’s website Encroachments (essentialenergy.com.au) and provide supporting\ndocumentation. Applicants are advised that fees and charges will apply where Essential Energy provides this\nservice.\nCouncil’s and the applicant’s attention is also drawn to Section 49 of the Electricity Supply Act 1995 (NSW).\nRelevantly, Essential Energy may require structures or things that could destroy, damage or interfere with\nelectricity works, or could make those works become a potential cause of bush fire or a risk to public safety, to\nbe modified or removed.\nEssential Energy makes the following general comments:\n• If the proposed development changes, there may be potential safety risks and it is recommended that\nEssential Energy is consulted for further comment;\n• As part of the subdivision, an easement is created for any existing electrical infrastructure. The\neasement is to be created using Essential Energy’s standard easement terms current at the time of\nregistration of the plan of subdivision;\n• Any existing encumbrances in favour of Essential Energy (or its predecessors) noted on the title of the\nabove property should be complied with;\n• Council should ensure that a Notification of Arrangement (confirming satisfactory arrangements have\nbeen made for the provision of power) is issued by Essential Energy with respect to all proposed lots\nwhich will form part of the subdivision, prior to Council releasing the Subdivision Certificate. It is the\nApplicant’s responsibility to make the appropriate application with Essential Energy for the supply of\nelectricity to the subdivision, which may include the payment of fees and contributions;\n• Any activities in proximity to electrical infrastructure must be undertaken in accordance with the latest\nindustry guideline currently known as ISSC 20 Guideline for the Management of Activities within\nElectricity Easements and Close to Infrastructure;\n• Prior to carrying out any works, a “Dial Before You Dig” enquiry should be undertaken in accordance\nwith the requirements of Part 5E (Protection of Underground Electricity Power Lines) of the Electricity\nSupply Act 1995 (NSW); the location of overhead and underground powerlines are also shown in the\nLook Up and Live app essentialenergy.com.au/lookupandlive.\n• Given there is electricity infrastructure in the area, it is the responsibility of the person/s completing\nany works around powerlines to understand their safety responsibilities. SafeWork NSW\n(www.safework.nsw.gov.au) has publications that provide guidance when working close to electricity\ninfrastructure. These include the Code of Practice - Work near Overhead Power Lines and Code of\nPractice - Work near Underground Assets.\n(A21) Planning Agreement\nPrior to the issue of a Construction Certificate, a Planning Agreement must be entered into in accordance with\nthe submitted Letter of Offer, prepared by Habitat Planning, dated 8 April 2024. A Planning Agreement must be\nentered into requiring a maximum financial contribution to Council the sum of $180,000, in recognition of a\nshortfall in the provision of 12 onsite car parking spaces ($15,000 per space). Should a detailed parking\nassessment, completed by a suitably qualified professional, be provided to, and approved by Council, a lesser\nfinancial parking contribution may be considered.\nThe Planning Agreement is to apply to LOT PT20 DP 780123, 481 Swift Street, LOT PT20 Sec 24 DP 780123, 485\nSwift Street & LOT 1 DP 912511, 487 Swift Street. The Draft Planning Agreement will be required to advertised\nin accordance with AlburyCity Community Participation Plan 2020.\n(A22) Encroachment over Council land\nAs the proposed awning structure encroaches over Council’s road reserve, the following matters must be\ncompleted prior to the issue of a Construction Certificate:\na) The owner/s shall obtain consent for the awning structure encroachment from Council under Section 138 of\nthe Roads Act 1993 and Section 68 of the Local Government Act 1993.\nb) The owner/s shall also complete a Licence Agreement with Council in accordance with Council’s Licence\nAgreement - Encroaching Structures.\nc) The owner shall supply plans and elevations of the proposed awning defining the extent of the\nproposed encroachment with the application for a Licence Agreement. An initial licence fee will be payable for\nthe creation of the licence in accordance with Section 4.7 of Council’s Encroachment on Council Land Policy\n2016.\nAll costs associated with the required consents and licenses including, without limitation, the\npreparation of the Licence Agreement, Public liability Insurance, Council’s legal costs and any costs\nassociated with the ongoing management, repair and maintenance of the Encroachment shall be at the\nexpense of the owner.\n(A23) Structural adequacy of awning\nThe awning overhanging the public footpath shall be maintained in good condition and continually remain\nstructurally adequate for the term of the development. Council recommends that a registered and suitably\nqualified Structural Engineer carry out an inspection and provide an inspection report to\nthe owner at five year intervals. Any rectification work and/or cost associated in maintaining the\nawning in a safe condition shall be at the owner’s expense.\n(A24) Plant, equipment or features on roof\nNo plant, equipment, services or architectural features other than those shown on the approved plans are\npermitted above the roof level of the building, without the written consent of Council.\n(A25) Heritage conservation\nThe demolition of two heritage items at 485 and 487 Swift Street is approved under this consent providing the\nfollowing matters are satisfactorily addressed prior to any works occurring on site:\na) A photographic archival record of all three cottages is undertaken and submitted and approved to/by\nCouncil prior to demolition.\nb) The verandah columns and finials of the central cottage (No 485) are to be salvaged and made available to\nthe second hand building market.\nc) The joinery items of the two brickwork cottages (Nos. 481 and 485), such as doors and windows, both\ninternally and externally should be salvaged and made available to the second hand building market where\nother building owners in the town can assess them for incorporation into their properties for conservation\nor restoration works.\nd) A permanent interpretation panel displaying an image of each of the three cottages along with a brief\nhistory of the cottages and their association with the Abikhair family is to be included and located in a\npublicly accessible part of the new building. The design and location of the panel is to be subject to Council\napproval.\ne) No demolition of the dwelling located at 485 Swift St (Heritage Item 164 - Schedule 5 Albury LEP 2010) is to\noccur prior to a Construction Certificate being issued\n(A26) Albury Police requirements\nAlbury Police require the following safety and security measures to be addressed:\na) CCTV footage for this area covering the main entries and exits.\nb) CCTV cameras to be of high quality and replaced if damaged.\nc) Exposed brick to be covered and/or lackeyed with anti-graffiti paint.\nd) Rescue climb points throughout lower levels.\ne) Identify private parking and public parking through signage.\nf) All traffic management plans are to be reviews and approved by TMC and the Local Traffic Committee and\nMRPD Highway Sergeants.\nRecommendations:\n• It is recommended that the exterior of the building be constructed in a way, and from materials that\nensure the exterior cannot be climbed.\n• Doors that control access from carparks and the commercial tenancy to the residential parts of the\nbuilding should be locked and access should be controlled by electronic access control systems. These\ndoors should close automatically when not held open.\n• Elevator access to any floor other than ground floor should also be controlled electronically.\n• Doors to the internal staircase should only open from the outside of the staircase, except for the\nground floor to allow people to exit the building.\n• Below are links to the NSW Police Force Biz Safe and Home Safe Information Brochures, with guidance\non how to increase your security and safety:\no https://www.police.nsw.gov.au/__data/assets/pdf_file/0008/357056/292859_0615_G015397_NS\nW_Police_Brochure_-_Bizsafe.pdf\no https://www.police.nsw.gov.au/__data/assets/pdf_file/0020/113816/home_safe.pdf\n(A27) Resuscitation notice\nA warning and resuscitation notice, pursuant to Part 3 of the Swimming Pool Regulation 2018, shall be displayed\nin a prominent location within the Swimming pool enclosure.\nThe notice must contain the following-\n(i) “Young children should be actively supervised when using this swimming pool”, and\n(ii) “Pool gates must be kept closed at all times”, and\n(iii) “Keep articles, objects and structures clear of the pool fence at all times”, and\n(iv) A simple flow chart (which may be the flow chart depicted in the Cardiopulmonary Resuscitation\nGuideline) containing details of resuscitation techniques.\nThe notice shall be legible from a distance of at least 3 metres and maintained in a clearly legible condition.\nproperty and is to remain in place for the life of the development.\nDEMOLITION WORK\nB. BEFORE DEMOLITION WORK COMMENCES\n(B1) Prior to commencement of demolition works\nTwo days before any site works or demolition begins, the applicant must:\na) Notify the adjoining owners that work will commence\nb) Erect a sign at the front of the property stating that unauthorised entry is prohibited and showing the\ndemolition contractor’s name, licence number, phone number and site address.\nc) Provide a temporary on-site toilet.\nd) Protect and support any neighbouring buildings.\ne) Protect any public place from damage, obstruction, or inconvenience from the carrying out of the\nconsent.\nf) Prevent any substance from falling onto a public place.\ng) Protect Council’s stormwater system, natural water courses and neighbouring properties from\nuncontrolled stormwater.\nh) Implement erosion and sediment control measures.\ni) Provide temporary safety fencing to restrict access to the site during works and until satisfactory\ninspection by Albury City Council.\nj) Follow any other conditions prescribed in the Environmental Planning and Assessment Regulation 2021.\nPrior to demolition, all services are to be suitably disconnected and capped off or sealed to the satisfaction of\nthe relevant service authority requirements. All demolition and excavated material is to be disposed of at a\nCouncil approved site or waste facility. Details of the proposed disposal location(s) of all excavated material from\nthe development site is to be provided to Albury City Council prior to commencement of demolition.\nRemoval and disposal of the asbestos containing material must be in accordance with the Protection of the\nEnvironment Operations Act 1997, Protection of the Environment Operations (General) Regulation 2009,\nProtection of the Environment Operations (Waste) Regulation 2014 and the Contaminated Land Management\nAct 1997.\nWhere water and wastewater services exist to the property and the services will be reused after demolition;\na) Sewer shall be disconnected and capped by a licensed Plumber. Protection of the service shall be provided\nto prevent damage.\nb) Water shall be disconnected and capped by a licensed Plumber on the property side of the water meter.\nThe water meter assembly and water meter shall be protected to prevent damage.\nErosion and sediment control measures must address and incorporate general site management material\nhandling practices, soil stabilisation, wind erosion, access measures and shall provide for:\n(a) The diversion of uncontaminated run-off around cleared or disturbed areas\n(b) The erection of a silt fence to prevent debris escaping into drainage systems or waterways\n(c) The prevention of tracking of sediment by vehicles onto roads\n(d) The stockpiling of topsoil, excavated material, construction and landscaping supplies and debris\nwithin the site, and the removal or utilisation (where appropriate) of that stockpile after completion of the\nworks.\n(e) Maintenance of control measures until the land is effectively rehabilitated and stabilised beyond the\ncompletion of construction.\nand lead contamination, dust, stormwater runoff, sediment loss, placement of building materials and wastes,\nrubbish, footway and laneway interference, traffic movement, hours of operation, and the like.\n(C3) Asbestos management\nAsbestos that is removed from the site must be taken to a waste management facility that is approved to accept\nasbestos. The asbestos must be declared to the waste management facility prior to disposal.\nodour created to the satisfaction of Council.\na suitably qualified person, must be submitted to the certifying authority & Council within 14 days of\ncompletion of the demolition work.\napplication.\nb) Provide for drainage discharge to an existing Council drainage system.\nc) Maintain where relevant existing stormwater overland flow paths.\nd) Ensure that the development either during construction or upon completion, does not impede or direct\nnatural surface water runoff so as to cause a nuisance to adjoining properties.\nDetails including easements to be created are to be included with the plans and specifications to accompany any\nConstruction Certificate or Subdivision Works Certificate.\nb) Provisions for public safety;\nc) Pedestrian and vehicular site access points and construction activity zones;\nd) Details of construction traffic management including:\ni. Proposed truck movements to and from the site;\nii. Estimated frequency of truck movements;\niii. Location of parking for construction vehicles; and\niv. Measures to ensure pedestrian safety near the site;\ne) Details of bulk earthworks to be carried out;\nf) Locations of site office, site facilities, temporary sanitary facilities and any storage areas for materials\nrelated to\nthe project;\ng) The equipment used to carry out works;\nh) Detail the methods of implementation and communication to all contractors of the requirements of the\nWaste Management Plan for the site\ni) Identify the designated location for garbage/waste containers with tight-fitting lid\nj) Outline the means to minimise and manage dust, noise and vibration generation from the construction\nworks;\nk) Noise management measures to be provided for plant and equipment; and\nl) Protection measures for adjoining properties, pedestrians, vehicles and public assets;\nm) The protective measures for the preservation of trees in adjoining public areas including measures in\naccordance with:\ni. AS 4970 - Protection of trees on development sites;\nii. An arborist’s report approved as part of this consent.\nA copy of the construction site management plan must be kept on-site at all times while work is being carried\nout.\n(E5) Silver level design\nThe Construction Certificate plans shall demonstrate that at least 20% of all apartments are designed to\nincorporate the Liveable Housing Australia (LHA) Silver Level requirements in accordance with the Liveable\nHousing Design Guidelines.\n(E6) Soil and Water Management Plan\nPrior to issue of a Construction Certificate, an Erosion and Sediment Control Plan (ESCP) prepared in accordance\nwith Albury City Council’s Soil and Water Management Policy is to be submitted to Council for approval. This plan\nis to confirm the capacity of drainage infrastructure to service the development, treat and retard stormwater,\nand reduce any impacts on soil and water downstream of the proposed development.\nThe erosion and sediment control measures must address and incorporate general site management material\nhandling practices, soil stabilisation, wind erosion, access measures and shall provide for (as a minimum):\na) Prevent site vehicles tracking sediment and other pollutants from the site area.\nb) Protect retained vegetation by a suitable barrier.\nc) Divert in an approved manner upslope water around cleared and/or disturbed areas.\nd) Prevent debris escaping off-site by use of on-site sediment barriers.\ne) Provide for stockpiles and building material that don’t create nuisance or pollution.\nf) Prevent dust nuisance.\ng) Ensure maintenance of all erosion control measures at operational capacity until the site is effectively\nrehabilitated.\nA copy of the ESCP must be kept on-site at all times and made available to Council’s Officer on request.\n(BW1-053)\n(E7) Retaining wall design\nAn appropriately qualified person shall design retaining walls or other approved methods necessary to prevent\nthe movement of excavated or filled ground, together with associated stormwater drainage measures. Details\nare to be included with the plans and specifications to accompany any Construction Certificate.\nmaterial or colour descriptions or use terminology such as ‘or similar’.\nNote: The building render plans currently show the service room located in the southwest corner as being\nconstructed with the light, earthy brickwork as proposed for the primary building. However, it is acknowledged\nand accepted that the final finish of the service room will be of the same or similar material as that used for the\nlift core.\n(E9) Structures near existing assets\nNo structure shall encroach onto, or exert any load on, the utilities within easements without approval from\nAlburyCity. Structures located within an easement, or adjacent to existing infrastructure, must extend to a minimum\nof 300mm below the invert of the existing asset, in accordance with Albury City Guidelines.\nDepartment prior to a Construction Certificate being issued and may require an approved pre-treatment device\n(eg. oil/grease arrestor, separators, etc) to be installed.\nThe application must:\na) Include detailed hydraulic plans indicating the size, type, and location of pre-treatment devices. All\nplumbing and drainage installations to these devices shall comply with AS/NZS3500.\nb) Be lodged via the NSW Planning Portal.\nThis development will be required to meet discharge standards in accordance with Council’s Trade Waste\nPolicy.\nNote: A Trade Waste Application form can be downloaded from AlburyCity’s website\n2. Detailed hydraulic plans shall be submitted with all trade waste applications which indicate size, type and\nlocation of pre-treatment devices. All plumbing and drainage installations to these devices shall comply\nwith AS/NZS3500.\n3. Pursuant to Section 68 of the Local Government Act 1993, to ensure there is no unacceptable discharge\nto Council’s sewerage system an approved pre-treatment device (eg. Oil/grease traps, separators, etc)\nshall be installed to details approved. The development will be required to meet discharge standards in\naccordance with Council’s Trade Waste Policy.\nBased on the findings of the DSI and if necessary, a Remediation Action Plan (RAP) will be required to be prepared\nto outline the appropriate remediation strategies and cleanup criteria to ensure the site is suitable for the\nproposed residential development.\nThe findings of the DSI and RAP shall be submitted to Council for review and approval prior to the issue of the\nConstruction Certificate.\n(E16) Bin storage room\nBefore the issue of a construction certificate, detailed plans of the waste storage room must be prepared by a\nsuitably qualified person.\nAn adequate waste receptacle area shall be provided on-site to store all waste pending disposal. The waste\nreceptacle area shall be enclosed, constructed of impervious coated/treated walls, floor, and ceiling surface.\nThe floor of such area shall be smooth, graded and drained to a floor waste connected to the sewer. The waste\nreceptacle area is to be equipped with a suitably located tap and hose (hose cock must be protected from the\nwaste bins).\nThe TMP shall include;\na) the identification on site of a tree protection zone (TPZ),\nb) methods of construction to minimise damage to the root zone of the tree and crown reduction to\nAustralian Standards.\nWhere possible, no excavation or soil level changes should take place within the TPZ as specified in the\nAustralian Standard - Protection of trees on development sites (AS 4970-09).\nThe tree management plan is to be submitted to Albury City Council for approval prior to application for a\nrelevant Construction Certificate.\nThe approved TMP is to be submitted to the Principal Certifying Authority, a minimum of 2 days prior to the\ncommencement of site works. All tree protection measures are to be carried out and comply with the\nsubmitted TMP before the commencement of any works on site and shall remain on site until the end of\nconstruction.\n(E18) Waste disposal\nPrior to the issue of a Construction Certificate, amended plans are required to be submitted showing a waste\ndisposal chute which residents can access on each floor. The disposal chute is to provide for three (3) waste\nstreams (general waste, recycling, and green waste). To facilitate the garbage disposal chute/waste storage,\neach chute must be able to taper into 3 separate bins to ensure effective and manageable waste collection and\nsorting.\nAn Operational Waste Management plan is required to be prepared in consultation with AlburyCity Council and\nis to include details in relation to management/storage, type of bins, bulky waste storage area (not suitable for\nchutes), number of bins and bin sizes, collection method (ie AlburyCity Service or private contractor, infirm\nservice, collection frequency), details on transporting waste/rubbish bins to and from storage and collection\nareas and management of amenity impacts such as noise and odour. The Operational Waste Management plan\nis to be submitted to Council prior to the issue of a Construction Certificate.\n(E19) Waste Management Plan\nA Waste Management Plan to address waste removal once the site is operational is to be prepared and submitted\nto Council prior to the application of a Construction Certificate. The plan shall address at a minimum the following\ninformation:\na) Identify how regularly waste will be collected from the site.\nb) To maximise recycling, the waste receptacle area must be equipped with separate waste bins to allow\nfor the sorting and separation of waste into the following waste streams - organic, recyclables and\ngeneral waste. Each waste stream must be separated and clearly labelled.\nc) Any waste storage bins shall be fitted with closing lids and shall be collected by licensed contractors\nbetween the hours of 9:00am and 5:00pm, Monday to Friday.\nd) Any approved waste storage area must be appropriately maintained to prevent litter, odour, and the\nentry of pests.\ne) All liquid trade waste discharged to the sewerage system, must comply with the trade waste approval\nissued by the relevant authority.\nf) All liquid trade waste pre-treatment devices must be regularly maintained to remain effective in\naccordance with the conditions of the liquid trade waste approval issued by the relevant authority.\n(E20) Alterations to pedestrian refuge island and Swift Street car parking\nDetailed engineering plans are to be submitted to Council identifying the proposed pedestrian refuge island\nalteration to enable vehicle access from Swift Street into the development. The plans should also identify the\nrelocation of Swift Street car parking spaces adjacent to the subject site. The plans will be subject to Council’s\napproval prior to the issue of the Construction Certificate.\n(E21) Construction certificate - landscape plan\nPrior to issue of construction certificate a Detailed Landscape Plan that includes the following will be required:\na) Identification and accurate mapping, that is location of the trunk and dimensions of the canopy, of all trees\nby a suitably qualified arborist (AQF - Level 5) in health and condition suitable for retention.\nb) Report prepared by a suitably qualified arborist (AQF - Level 5) detailing species, health, condition of all\ntrees. Identification of trees suitable for retention, hazard rating and remedial works were required .\nc) Trees identified for retention to be clearly tagged on site to allow for assessment by Council officers.\nd) A street tree and/or if relevant a open space planting plan detailing species (both botanical and common\nnames) and location.\ne) Methods of tree protection, as per the Australian Standard (AS4970 '2009) Protection of Trees on\nDevelopment Sites\" during engineering works for trees identified to be retained. Tree Protections Zones have\nto be clearly indicated on the trees identified for retention.\nthe Supervisor Trees and Streetscapes, Leanne Hunichen. Leanne can be contacted on 0418 933 257. The\nadditional street tree is to be a super advanced Platanus x acerfolia\n• The resubmitted landscape is to identify the additional street tree to the east of the crossover and tree\nprotection zones of the retained trees, regardless of the spatial constraints\n• The replacement street tree identified on the original landscape plan is to be a super advanced Platanus x\nacerfolia. No structured soil is required. This work is to be carried out by the Developer under the\nsupervision of the Supervisor Trees and Streetscapes, Leanne Hunichen. Leanne can be contacted on 0418\n933 257.\nswimming pool and spa filtration systems.\nThe report shall confirm the noise levels predicted during operation and provide recommendations for noise\nmitigation measures. These measures must be incorporated into the design of the Development to achieve\nnoise reduction levels for each type of plant and equipment and where necessary, include the provision of\nacoustic soundproof housing.\nThe report is to be prepared by a suitably qualified Acoustic Practitioner.\nAll plant and equipment associated with the Development are to be maintained such that they are in good\nworking order.\nacoustic report prepared by Marshall Day Acoustics have been incorporated into the design; and\nb) Demonstrate that the development will comply with the noise criteria as detailed in the acoustic\nassessment.\nPlans shall be submitted to Council for review and approval prior to the issue of the Construction Certificate.\nF. BEFORE BUILDING WORK COMMENCES\n(F1) Prior to commencement of Construction Works\nTwo days before any site works or building begins, the applicant must:\na) Provide Notice of commencement of work and appointment of Principal Certifying Authority; to the\nCouncil.\nb) Notify the adjoining owners that work will commence.\nc) Notify the Council of the name, address, phone number and licence number of the builder.\nd) Erect a sign at the front of the property stating that unauthorised entry is prohibited and showing the\nbuilder’s name or Owner builder details (as applicable), licence number, phone number and site\naddress.\ne) Protect and support any neighbouring buildings, trees, structures or works on adjoining land from\npossible damage from the excavation and if necessary, underpin the building, structure or work on\nadjoining land to prevent damage from the excavation, at the person’s with the benefit of the consents\nown expense.\nf) Protect any public place from damage, obstruction or inconvenience from the carrying out of the\nconsent.\ng) Prevent any substance from falling onto a public place.\nh) Follow any other conditions prescribed in the Environmental Planning and Assessment Regulation 2021\ni) The vegetation/tree protection measures are to be certified by the relevant Council officer prior to the\ncommencement of works\nThe Plumbing application shall include plans of the following:\na) Sanitary plumbing and drainage\nb) Fire services, incorporating appropriate backflow prevention devices in accordance with\nAS/NZS3500.1:2021 and the Plumbing Code of Australia\nc) Stormwater with pipe sizes, grades and invert levels, catchment areas for pits and point of discharge.\nd) The plans are to be prepared by a suitably qualified hydraulics consultant.\nAll plumbing and drainage work is to be carried out by a NSW Licensed Plumber and Drainer and to the\nrequirements of the Plumbing and Drainage Act and to the Local Government Act of NSW. The Licensed\nPlumber’s details are to be forwarded to Council prior to commencement of any plumbing work.\nThe sign is to be maintained until a relevant Occupation Certificate has been issued for the swimming pool.\nfor Building Sites.\nErosion and sediment control measures must address and incorporate general site management material\nhandling practices, soil stabilisation, wind erosion, access measures and shall provide for:\n(a) The diversion of uncontaminated run-off around cleared or disturbed areas\n(b) The erection of a silt fence to prevent debris escaping into drainage systems or waterways\n(c) The prevention of tracking of sediment by vehicles onto roads\n(d) The stockpiling of topsoil, excavated material, construction and landscaping supplies and debris\nwithin the site, and the removal or utilisation (where appropriate) of that stockpile after completion of the\nworks.\n(e) Maintenance of control measures until the land is effectively rehabilitated and stabilised beyond the\ncompletion of construction.\nreason of noise, vibrations, smells, dust, stormwater runoff, sediment loss, placement of building materials and\n(BW3-033)\n(G3) Hours of work\nDemolition, subdivision, or construction works will be restricted to the following hours in accordance with the\nNSW Environment Protection Authority Noise Control Guidelines:\na) Mondays to Fridays, 7.00am to 6.00pm\nb) Saturdays, 8.00am to 1.00pm\nc) No work is permitted on Sundays and Public Holidays.\nConstruction works that are carried out in the open that involve the use of heavy vehicles, heavy machinery and\nother equipment likely to cause offence to adjoining properties is to be restricted to the above hours in\naccordance with the NSW Environment Protection Authority Noise Control Guidelines.\nNote: The provisions of the Protection of the Environment Operations Act, 1997 in regulating offensive noise also\napply to all construction works.\nfollowing:\na) Method of protection\nb) The date of installation of the system\nc) Where a chemical barrier is used, its life expectancy as listed on the National Registration Authority for\nAgricultural and Veterinary Chemicals Label\nd) The need to maintain and inspect the system on a regular basis.\nRedundant vehicle crossing(s) shall be removed and replaced with Council’s standard kerb and gutter and foot\npaving.\nconsistent with the latest version of Australian Standard 3500.3.2018.\nparticularly at night and over the weekend.\nAll waste material not required for further on-site processing or for re-use on the site, must be regularly removed\nfrom the site to be recycled or disposed of at a Council approved waste facility. All vehicles removing waste must\nhave fully secured and co ntained loads so that no waste is spilled, or dust or odour created, to the satisfaction\nof Council.\nconstructed so as to deny any flow of water into or around the building or neighbouring buildings or onto\nneighbouring lands.\nConsent shall be obtained from the appropriate authority for any earthworks or retaining walls not forming part\nof this development consent and approved plans if it is:\na) Within 900mm of a property allotment boundary or,\nb) Results in a cut or fill greater than 600mm\nc) If the retaining wall height is greater than 600mm (including the height of any earth batters) or,\nd) Is located within 1.0 metre of any registered easement, and/or other service pipe such as a sewer main,\nstormwater main, or water main\nThe following details are to be placed on signs to be erected on the site:\na) The name of the Principal Certifying Authority, their address and telephone number,\nb) The name of the person in charge of the work site and telephone number at which that person may be\ncontacted during work hours,\nc) That unauthorised entry to the work site is prohibited,\nd) The designated waste storage area must be covered when the site is unattended, and\ne) All sediment and erosion control measures is to be fully maintained until completion of the construction\nphase.\nSignage but no more than 2 signs stating the above details are to be erected:\n(i) At the commencement of, and for the full length of the construction works onsite, and\n(ii) In a prominent position on the work site and in a manner that can be easily read by pedestrian traffic.\nAll construction signage is to be removed when the Occupation Certificate has been issued for the development,\nor all construction signage is to be removed on completion of earthworks or construction works and when a\nCompliance Certificate has been issued by the Principal Certifying\nAuthority certifying that the development has complied fully with the development consent and, where required,\nbeen constructed in accordance with the Construction Certificate.\nThe two existing trees are to be hydro excavated along the boundary for excavation works and any roots found\nlarger than 50mm are to be reported to AlburyCity’s Trees and Str eetscapes team immediately for inspection.\nRoot barrier is to be placed along the new structure to reduce future root incursion.\nThe person with the benefit of this consent shall contact Council’s Trees and Streets Supervisor prior to\nconstruction works occurring on site for inspection of TPZ.\nb) Have only one connection to the main line of sanitary house drain with a property vertical shaft provided\nat the point of connection to Council’s sewer main.\nThe development is to be provided with its own:\ni. Inspection shaft immediately upstream of the junction with the main line of the sanitary house drain.\nii. An Overflow Relief Gully\niii. An open upstream vent.\n(G18) Drainage of overflow water\nAdequate surface water and stormwater measures must be installed surrounding the proposed development.\nThis is required to cater for the potential of swimming pool overflow and surface water runoff from hardstand\npavement surfaces entering and causing nuisance to adjoining properties.\nAny such method utilised to collect and direct pool overflow water and/or surface water to a lawful point of\ndischarge shall be consistent with the latest version of Australian Standard 3500.3.2015.\nplans, or\nb) A temporary child resistant barrier is installed to the satisfaction of the Principal Certifier. i.e. “The\nCertifier”\nAny temporary child resistant barrier is to be maintained until such time as a compliant, permanent child\nresistant barrier is in place.\n(G26) Ground Floor Parking:\n• Painted pedestrian path (zebra marking) to be implemented from disability parking space to entrance on\nground floor\n• Bicycle parking to be provided in accordance with AS2890.3, specifically:\no Bicycle parking facilities shall be designed;\na) So they are safe for all users of the designated space, securely fixed and conveniently\nlocated for users;\nb) To accommodate and support a standard bicycle with sufficient space so as to minimise\ndamage while parked and during movement into or out of the parking space (see figures 2.1 and\n2.2 in AS2890.3)\nc) To suit the particular location\nd) So that facilities do not obstruct or hinder pedestrian access ways\ne) To include a minimum of 20% of ground level (horizontal) BPS in any bicycle parking facility.\nNOTE: This is to provide for those riders unable to lift a bicycle to a hanging BPD, and parking of\nnon-standard bicycles\n• “Watch out for cyclists” signage and/or pavement markings to be implemented in ground floor parking area,\ndue to potential conflict between vehicles and bikes\n(G27) Vehicle manoeuvring and car parking areas\nAll car spaces provided within the site shall be designed to comply with AS2890 series. The minimum dimensions\nfor a two-way internal roadway are to be 5.8m and landscaped areas are to be protected from vehicle activity by\na minimum height 100mm kerb or similar barrier.\nAll parking spaces and manoeuvring areas must be designed to allow cars to drive in a forward direction, both\nwhen entering and leaving the site.\nAll car parking and circulation areas are to be finished with a fully sealed surface, drained and line marked, to\nprevent nuisance from dust, mud, drainage, sediment loss and the like. Such areas shall at a minimum be\nprovided with a bitumen seal, asphalt, or concrete.\nAll basement car parking spaces shall be equipped with the necessary infrastructure to be adapted to provide\nelectric vehicle charging.\nPlans are to be submitted to Albury City Council for approval prior to application for a relevant Construction\nCertificate.\nThe applicant shall install a watering system to ensure the health and minimise maintenance of landscaped areas.\nInstallation must be undertaken b y an appropriately licensed person in accordance with an approved plan\ncomplying with the provisions of the Local Government (Water, Sewerage and Drainage) Regulation 1993.\nrequired by the Building Code of Australia.\n(H7) Car parking contribution - Planning Agreement\nPrior to the issue of an Occupation Certificate, parking contributions as set out in the Planning Agreement must\nbe paid to AlburyCity Council.\n(H8) Certification of acoustic measures\nPrior to the issue of an Occupation Certificate, a suitably qualified person must provide details demonstrating\ncompliance to the Principal Certifier that the acoustic design mitigation measures have been installed in\naccordance with the Acoustic Assessment Report, approved under this consent. An Operational Plan of\nManagement must be submitted and endorsed by the Principal Certifier detailing: alternative ventilation\nmeasures; acoustic-rated windows and doors in accordance with the design solution; and any other design or\noperational management measures (required to ensure applicable amenity noise levels are met within each\ndwelling) as recommended in the acoustic assessment report and supplementary documents prepared by\nMarshall Day Acoustics.\n(H9) Swimming Pool Registration\nThe completed swimming pool/spa must be registered on the NSW Governments swimming pool register prior\nto use. The swimming pool register can be found on-line at the following link\nwww.swimmingpoolregister.nsw.gov.au\nincluding all purchasing and planting costs shall be at the developer’s expense.\nThe person with the benefit of this consent shall contact Council’s Trees and Streets Supervisor prior to the\nplanting of the street trees to confirm planting locations.\nWhere there is any proposed change in the BASIX commitments the applicant must submit a new BASIX\nCertificate to the Certifying Authority and Council. If any proposed change in the approved BASIX commitments\nare inconsistent with development consent (See: Clause 75 of the Regulation) the applicant will be required to\nsubmit an amended development application to Council pursuant to Section 4.55 of the Act.\nIf any of the vegetation comprising that landscaping dies or is removed, it is to be replaced with vegetation of\nthe same species and, to the greatest extent practicable, the same maturity, as the vegetation that died or was\nremoved.\n(b) all garbage and recyclable materials generated from the premises must be stored wholly within any\napproved storage area and must not be stored outside the premises (including any public place) at any\ntime.\n(c) waste collection and pick-up must only occur on-site, not kerbside.\n(d) arrangements must be implemented for the separation of waste into the following waste streams -\norganic, recyclables and general waste. Each waste stream must be separated and clearly labelled.\n(e) all waste storage bins must be fitted with closing lids and the waste storage area must be appropriately\nmaintained to prevent litter, odour, and the entry of pests and vermin.\n(f) where the collection of garbage and recyclable materials from the premises is undertaken by a licensed\ncontractor, it must only occur in accordance with the approved Waste Management Plan and be between\n9:00am to 5:00pm Monday to Friday.\n(g) must be accessible to waste collection vehicles.\n(h) all liquid trade waste discharged to the sewerage system, must comply with the trade waste approval\nissued by the relevant authority.\n(i) all liquid trade waste pre-treatment devices must be regularly maintained to remain effective in\naccordance with the conditions of the liquid trade waste approval issued by the relevant authority.\nThe NSW EPA’s Better practice guide for resource recovery in residential developments apply to this\ndevelopment.\nAll signs shall be located wholly within the allotment boundaries and shall not project over the street\nalignment, unless written consent from the adjoining landowner has been obtained.\nAll service vehicles and deliveries to the site shall be limited to these hours.\n(I9) Security alarms\nAll security alarms or similar devices installed on the land must be of a silent type in accordance with any\ncurrent standard published by Standards Australia and be connected to a security service. (F012)\n(I10) Deliveries and service vehicles\nDuring ongoing use of the commercial premises, all delivery and service vehicles generated by the\ndevelopment,\na) are undertaken only during the following hours:\nMonday to Sunday from 8am to 9 pm.\nb) must be loaded and unloaded within the confines of the allotment boundary and only occur in\ndesignated loading and unloading areas on the property\nc) must not obstruct vehicle access within Arnolds Lane\nd) do not occur on the street\ne) do not obstruct other operations\nf) minimise disruption to public spaces\ng) maintain a clear service vehicle dock, car parking spaces and access driveways at all times; and\nh) all vehicles must enter and leave in a forward direction.\nApplication to Council.\n(I12) Removal of graffiti\nThe finishes of all structures and buildings are to be maintained at all times and any graffiti or\nvandalism immediately removed/repaired.\n(I13) Storage of goods and signage\nAll goods and signage must be located wholly within the premises and must not be stored or displayed outside\nthe premises, including any public place, without Council's approval.\n(I14) Air conditioning noise\nIn accordance with the Protection of the Environment Operations (Noise Control) Regulation 2017, an air\nconditioner must not be used on residential premises in such a manner that it emits noise that can be heard\nwithin a habitable room in any other residential premises (regardless of whether any door or window to that\nroom is open):\na) before 8:00am or after 10:00pm on any Saturday, Sunday, or public holiday, or\nb) before 7:00am or after 10:00pm on any other day.\nexternal plant and equipment shall be required to be acoustically treated or placed in soundproof housing to\nreduce noise to a level satisfactory to Council.\n(b) The parking or movement of motor vehicles.\n(c) The transporting of materials or goods to or from the site.\n(d) The hours of operation.\n(e) Noise, air, lighting, and water discharges from the site.\n(f) Electrical interference.\n(g) The storage and handling of garbage, fuels, chemicals, pesticides, gasses, waste products or other materials.\n(h) Emissions or discharges into the surrounding environment including, from wastewater, sediment, dust,\nvibration, odours, or other harmful products.\nJ. BEFORE ISSUE OF AN SUBDIVISION CERTIFICATE\n(J1) Maintenance bond\nPrior to issue of a Subdivision Certificate, the applicant is to lodge with Council a maintenance bond equivalent to\nfive percent (5%) of the contract price of the subdivision works but not less than Five Thousand Dollars ($5000).\nSuch bond monies will be held for a minimum period of twelve (12) months at which time an assessment will be\nmade as to the extent of outstanding or substandard works. Those works deemed to be outstanding or of a\nsubstandard nature at that time by Council, might be repaired by Council at the applicant’s expense by drawing on\nthe bond monies held by Council.\nNote: Maintenance Bonds are only applicable for projects with a value greater than $50,000. (For office use only,\nHot Key 64)\nc) A letter of compliance from the relevant gas supplier.\nbeen satisfied or addressed satisfactorily shall be submitted to Council to confirm compliance.","stage":"general","stage_basis":"heading","page":10}]});
